typedef struct { long v0; long v1; } counters_t;

// Variant B: 64-byte padding per counter (no false sharing)
typedef struct { 
    long v0; 
    char pad0[64 - sizeof(long)]; 
    long v1; 
    char pad1[64 - sizeof(long)]; 
} counters_padded_t;
